create index if not exists video_events_rollup_idx on public.video_events(video_id,event_type,occurred_at desc);
create or replace function public.record_video_play(p_video_id uuid,p_anonymous_id uuid default null) returns void language plpgsql security definer set search_path='' as $$ declare v_uid uuid:=auth.uid(); begin if not exists(select 1 from public.videos where id=p_video_id and status='published'::public.video_status and published_at<=now()) then raise exception 'video unavailable'; end if; if v_uid is null and p_anonymous_id is null then raise exception 'viewer identity required'; end if; if not exists(select 1 from public.video_events e where e.video_id=p_video_id and e.event_type='play' and e.occurred_at>now()-interval '30 minutes' and ((v_uid is not null and e.viewer_id=v_uid) or (v_uid is null and e.viewer_id is null and e.anonymous_id=p_anonymous_id))) then insert into public.video_events(video_id,viewer_id,anonymous_id,event_type) values(p_video_id,v_uid,case when v_uid is null then p_anonymous_id else null end,'play'); end if; end $$;
revoke all on function public.record_video_play(uuid,uuid) from public; grant execute on function public.record_video_play(uuid,uuid) to anon,authenticated;
create or replace function public.get_video_view_counts() returns table(video_id uuid,view_count bigint) language sql stable security definer set search_path='' as $$ select e.video_id,count(*)::bigint from public.video_events e join public.videos v on v.id=e.video_id where e.event_type='play' and v.status='published'::public.video_status and v.published_at<=now() group by e.video_id $$;
revoke all on function public.get_video_view_counts() from public; grant execute on function public.get_video_view_counts() to anon,authenticated;
